package manifest

import (
	"fmt"
	"strconv"
)

// DocumentIndex marks a violation belonging to the document as a whole rather
// than to one asset entry — a malformed `sources` value, an unrecognized name
// in `harnesses`.
//
// It is negative so it sorts ahead of every asset entry without a special case
// in the comparison: a problem with the whole document is the one an author
// should read first, because it is the one that can explain the entries below
// it.
const DocumentIndex = -1

// Violation is one thing a decoded manifest says that harnaas cannot accept.
//
// Decoding stops at the first failure because a document that will not parse
// has no second problem to find. Interpretation does not stop: every asset entry
// is independent, so reporting one at a time would make a manifest with three
// mistakes three runs of the same command, each ending in a different sentence.
//
// A violation therefore carries where it is as data rather than only inside its
// sentence. That is what lets the aggregate order itself identically on every
// run — by [Violation.Index], then by [Violation.Field] — instead of inheriting
// the order a map happened to iterate in.
type Violation struct {
	// Index is the asset entry's position in `assets`, or [DocumentIndex] for a
	// violation about the document itself. It is the primary sort key.
	Index int

	// Field names the part of the document at fault in the author's own
	// vocabulary — `sources.acme`, `assets[2].scope` — so a reader knows which
	// line to open, and so two violations on one entry order deterministically.
	Field string

	// Problem states what is wrong, in one line.
	Problem string

	// Fix states the exact edit that resolves it. It is always an edit for a
	// person to make: harnaas does not write this file.
	Fix string
}

// String renders the location, the problem, a blank line, and the fix — the
// shape every user-facing diagnostic in harnaas takes.
//
// A violation is deliberately not an error. One of them is never what a command
// returns: interpretation collects them all and returns the aggregate, and a
// type that satisfied `error` would invite a caller to return the first one it
// saw, which is the behaviour accumulating exists to prevent.
func (v *Violation) String() string {
	return fmt.Sprintf("%s: %s\n\n%s", v.Field, v.Problem, v.Fix)
}

// sourceField names a `sources` entry, or the block itself where the entry has
// no key to be named by.
func sourceField(key string) string {
	if key == "" {
		return "sources"
	}
	return "sources." + key
}

// assetField names an asset entry.
func assetField(index int) string {
	return "assets[" + strconv.Itoa(index) + "]"
}

// assetSubject is how every message refers to an asset entry.
//
// An entry has no other stable name: its id may be the thing that is wrong, and
// its source string may be absent. The index is the one thing an author can
// always count to in the file, so it is worth spelling identically everywhere,
// which is why both decoding and interpretation phrase it here.
func assetSubject(index int) string {
	return fmt.Sprintf("the asset entry at index %d", index)
}

// sourceViolation reports a problem with a `sources` entry.
func sourceViolation(key, problem, fix string) *Violation {
	return &Violation{Index: DocumentIndex, Field: sourceField(key), Problem: problem, Fix: fix}
}

// assetViolation reports a problem with one field of an asset entry.
//
// The field is spelled the way the object form would carry it — `source`,
// `type`, `targets[1]` — so a violation raised about an entry written as a bare
// string still names something the author can act on, and so two violations on
// one entry order deterministically against each other.
func assetViolation(index int, field, problem, fix string) *Violation {
	return &Violation{Index: index, Field: assetField(index) + "." + field, Problem: problem, Fix: fix}
}

// assetSourceViolation reports a problem with an asset entry's source string.
//
// The source is attributed as a field even for an entry written in the string
// form, which declares no field name at all, because it is the field the object
// form would have carried and it is what a reader has to change either way.
func assetSourceViolation(index int, problem, fix string) *Violation {
	return assetViolation(index, "source", problem, fix)
}

package manifest

import (
	"fmt"
	"slices"
	"strings"

	"github.com/harnaas/harnaas/cmd/harnaas/cli/harness"
)

// Scope is where an asset's installed copy lives: beside the project, or in the
// target harness's own per-user location.
//
// It is declared per asset rather than chosen per run because it is a property
// of the content — a team's house-style rule belongs to the repository, a
// personal shortcut belongs to the person — and a flag would make one manifest
// install to two different places depending on who ran the command.
type Scope string

const (
	// ScopeProject installs beneath the project root of each target harness. It
	// is the default, and the only scope an instruction may take.
	ScopeProject Scope = "project"

	// ScopeUser installs into the target harness's per-user location, and is
	// accepted only for a harness the roster records as having an unambiguous
	// one.
	ScopeUser Scope = "user"
)

// scopes is every accepted scope, in the order every diagnostic lists them —
// the default first, because it is the one an author reading the list most
// often wants.
var scopes = []Scope{ScopeProject, ScopeUser}

// Asset is one manifest entry with every question about it answered: what it
// is, what it is called, which harnesses it is guaranteed for, and where it
// installs.
//
// Nothing here is optional. Every field an entry may leave undeclared has been
// inferred from its path or defaulted from the document by the time an Asset
// exists, which is what makes it the shape later phases read: `install` never
// has to know whether the author wrote `type` or relied on the directory name,
// and so cannot treat the two differently.
type Asset struct {
	// Index is the entry's position in the `assets` array, carried through
	// because it stays the way every diagnostic points at the line to edit.
	Index int

	// ObjectForm records whether the entry was written as an object, so a
	// remedy can direct an author to the object form only when they are not
	// already using it.
	ObjectForm bool

	// Ref is the parsed source string: which source, and the path within it.
	Ref AssetRef

	// Type is the asset's type, declared or inferred from the containing
	// directory.
	Type AssetType

	// ID is the asset's id, declared or inferred from the path's leaf.
	ID string

	// Targets is the effective target list: the entry's own `targets` where it
	// declared them, and the manifest's `harnesses` otherwise. It is never
	// empty — an asset with no target could never be installed anywhere, which
	// is a violation rather than a state an Asset can reach.
	Targets []harness.ID

	// Scope is where the asset installs, `project` unless the entry declared
	// otherwise.
	Scope Scope
}

// ResolveType returns the entry's type: the one it declares, or the one its
// path implies.
//
// A declared type suppresses inference entirely rather than being checked
// against it. The object form exists precisely for a source whose layout does
// not follow the convention, so comparing the two would refuse the case it was
// added for.
func ResolveType(entry AssetEntry, ref AssetRef) (AssetType, *Violation) {
	if entry.Type == "" {
		return InferType(entry.Index, ref)
	}

	declared := AssetType(entry.Type)
	if !slices.Contains(AssetTypes(), declared) {
		return "", assetViolation(entry.Index, "type",
			fmt.Sprintf("%s declares the type %q, which is not a type harnaas installs", assetSubject(entry.Index), entry.Type),
			fmt.Sprintf("Set %q on the entry in %s to one of %s.", "type", FileName, typeList()),
		)
	}

	return declared, nil
}

// ResolveID returns the entry's id: the one it declares, or the one its path's
// leaf implies.
//
// Inference is suppressed one field at a time, which is why this is a separate
// decision from [ResolveType]: an entry declaring `type` for an unconventional
// layout still wants its id inferred, and an entry declaring `id` because two
// sources use the same leaf still wants its type inferred.
//
// Whether the resulting id is usable — a single safe path segment, unique among
// assets of its type — is a question about the document rather than the entry,
// and is answered where every entry's id is in hand.
func ResolveID(entry AssetEntry, ref AssetRef) (string, *Violation) {
	if entry.ID == "" {
		return InferID(entry.Index, ref)
	}
	return entry.ID, nil
}

// ResolveTargets returns the harnesses an entry is guaranteed for: its own
// `targets` where it declared them, and the manifest's `harnesses` otherwise.
//
// A name inherited from `harnesses` is not checked here. It is checked once by
// [CheckHarnesses], because a misspelling in that one list is one mistake, and
// attributing it to every asset that inherited it would report the same edit
// once per entry and bury the entries with problems of their own.
//
// The result is a list of violations rather than one because `targets` is
// itself a list: two unrecognized names are two independent edits, and each is
// attributed to its own position so the aggregate orders them the same way on
// every run.
func ResolveTargets(entry AssetEntry, harnesses []string) ([]harness.ID, []*Violation) {
	// A nil slice is an undeclared field and an empty one is a declared empty
	// list. Both leave the asset with nowhere to install, but the edit that
	// fixes them is different, so decoding kept them distinguishable and this
	// is where the distinction is spent.
	if entry.Targets == nil {
		if len(harnesses) == 0 {
			return nil, []*Violation{assetViolation(entry.Index, "targets",
				fmt.Sprintf(
					"%s has no target harness: it declares no %q and the manifest declares no %q",
					assetSubject(entry.Index), "targets", "harnesses",
				),
				fmt.Sprintf(
					"Add a %q list to %s naming at least one of %s, or declare %q on this entry.",
					"harnesses", FileName, harnessList(), "targets",
				),
			)}
		}
		return toHarnessIDs(harnesses), nil
	}

	if len(entry.Targets) == 0 {
		return nil, []*Violation{assetViolation(entry.Index, "targets",
			fmt.Sprintf(
				"%s declares an empty %q list, so it could never be installed anywhere",
				assetSubject(entry.Index), "targets",
			),
			fmt.Sprintf(
				"Name at least one of %s in the entry's %q, or remove the field so the asset inherits the manifest's %q.",
				harnessList(), "targets", "harnesses",
			),
		)}
	}

	var violations []*Violation
	targets := make([]harness.ID, 0, len(entry.Targets))
	for position, name := range entry.Targets {
		id := harness.ID(name)
		if !harness.Recognized(id) {
			violations = append(violations, assetViolation(entry.Index, fmt.Sprintf("targets[%d]", position),
				fmt.Sprintf(
					"%s targets %q, which is not a harness harnaas recognizes",
					assetSubject(entry.Index), name,
				),
				fmt.Sprintf("Change it in %s to a harness harnaas recognizes: %s.", FileName, harnessList()),
			))
			continue
		}
		targets = append(targets, id)
	}
	if len(violations) > 0 {
		return nil, violations
	}

	return targets, nil
}

// CheckHarnesses reports every name in the manifest's `harnesses` list the
// roster does not recognize.
//
// An empty list is not reported here. It is only a problem for an asset that
// would have inherited it, and an asset declaring its own `targets` is
// perfectly well served by a manifest that declares no default — so the
// violation belongs to the entry that has nowhere to go, not to the document.
func CheckHarnesses(harnesses []string) []*Violation {
	var violations []*Violation
	for position, name := range harnesses {
		if harness.Recognized(harness.ID(name)) {
			continue
		}

		violations = append(violations, &Violation{
			Index: DocumentIndex,
			Field: fmt.Sprintf("harnesses[%d]", position),
			Problem: fmt.Sprintf(
				"the %q list names %q, which is not a harness harnaas recognizes",
				"harnesses", name,
			),
			Fix: fmt.Sprintf("Change it in %s to a harness harnaas recognizes: %s.", FileName, harnessList()),
		})
	}
	return violations
}

// ResolveScope returns where the entry installs: the scope it declares, or
// `project`.
func ResolveScope(entry AssetEntry, assetType AssetType, targets []harness.ID) (Scope, *Violation) {
	return resolveScope(entry, assetType, targets, harness.HasPerUserLocation)
}

// resolveScope is [ResolveScope] with the roster query as a parameter.
//
// The seam exists because the roster is data this package cannot vary: today
// every recognized harness has a per-user location, so the rule that `user`
// scope is refused where one does not exist would have no test at all, and
// would be free to rot until the first harness that lacks one is added — which
// is exactly when a silent fall back to project scope would start installing
// assets somewhere nobody asked for.
func resolveScope(
	entry AssetEntry,
	assetType AssetType,
	targets []harness.ID,
	perUserLocation func(harness.ID) (bool, error),
) (Scope, *Violation) {
	if entry.Scope == "" {
		return ScopeProject, nil
	}

	declared := Scope(entry.Scope)
	if !slices.Contains(scopes, declared) {
		return "", assetViolation(entry.Index, "scope",
			fmt.Sprintf("%s declares the scope %q, which harnaas does not define", assetSubject(entry.Index), entry.Scope),
			fmt.Sprintf(
				"Set %q on the entry in %s to one of %s, or remove it to install at %q scope.",
				"scope", FileName, scopeList(), ScopeProject,
			),
		)
	}
	if declared == ScopeProject {
		return ScopeProject, nil
	}

	// An instruction is guidance concatenated into a committed memory file, and
	// what distinguishes it from a rule is surviving a fresh clone inside that
	// file. At user scope there is no clone and no committed file, so the type
	// would mean nothing — this is definitional, not a limitation of the
	// installer.
	if assetType == AssetTypeInstruction {
		return "", assetViolation(entry.Index, "scope",
			fmt.Sprintf(
				"%s is an %s at %q scope, and an %s exists only inside the project's committed memory file",
				assetSubject(entry.Index), AssetTypeInstruction, ScopeUser, AssetTypeInstruction,
			),
			fmt.Sprintf(
				"Remove %q from the entry in %s, or declare its %q as %q, which is the type for always-on guidance outside a committed file.",
				"scope", FileName, "type", AssetTypeRule,
			),
		)
	}

	var unsupported []string
	for _, target := range targets {
		hasLocation, err := perUserLocation(target)
		if err != nil {
			// The target is not in the roster, which [ResolveTargets] or
			// [CheckHarnesses] has already reported against the field that
			// declared it. Reporting it a second time as a scope problem would
			// name an edit that does not fix it.
			continue
		}
		if !hasLocation {
			unsupported = append(unsupported, quoted(string(target)))
		}
	}

	if len(unsupported) > 0 {
		return "", assetViolation(entry.Index, "scope",
			fmt.Sprintf(
				"%s declares %q scope, and %s no unambiguous per-user location",
				assetSubject(entry.Index), ScopeUser, hasNo(unsupported),
			),
			fmt.Sprintf(
				"Remove %q from the entry in %s so it installs at %q scope, or narrow the entry's %q to harnesses with a per-user location.",
				"scope", FileName, ScopeProject, "targets",
			),
		)
	}

	return ScopeUser, nil
}

// toHarnessIDs converts a declared name list into roster ids. It is only ever
// called with names already checked against the roster, or with the manifest's
// `harnesses` list, whose names [CheckHarnesses] reports on separately.
func toHarnessIDs(names []string) []harness.ID {
	ids := make([]harness.ID, 0, len(names))
	for _, name := range names {
		ids = append(ids, harness.ID(name))
	}
	return ids
}

// hasNo renders the offending targets as the subject of a sentence, so one
// target reads as naturally as several.
func hasNo(targets []string) string {
	if len(targets) == 1 {
		return "the target " + targets[0] + " has"
	}
	return "the targets " + strings.Join(targets, ", ") + " have"
}

// typeList renders every asset type for a diagnostic, in the fixed order
// [AssetTypes] gives.
func typeList() string {
	names := make([]string, 0, len(AssetTypes()))
	for _, assetType := range AssetTypes() {
		names = append(names, quoted(string(assetType)))
	}
	return strings.Join(names, ", ")
}

// scopeList renders every accepted scope for a diagnostic.
func scopeList() string {
	names := make([]string, 0, len(scopes))
	for _, scope := range scopes {
		names = append(names, quoted(string(scope)))
	}
	return strings.Join(names, ", ")
}

// harnessList renders every recognized harness id for a diagnostic, in the
// roster's own order so two runs produce the same sentence.
func harnessList() string {
	ids := harness.IDs()
	names := make([]string, 0, len(ids))
	for _, id := range ids {
		names = append(names, quoted(string(id)))
	}
	return strings.Join(names, ", ")
}

package manifest

import (
	"fmt"
	"path"
	"slices"
	"strings"
)

// AssetType is what an asset is, in the vocabulary the harnesses and this
// project share: a skill, a rule, an instruction, a command or a persona.
type AssetType string

const (
	// AssetTypeSkill is an asset the harness loads on its own initiative when
	// its description matches the task at hand.
	AssetTypeSkill AssetType = "skill"

	// AssetTypeRule is always-on guidance installed as its own file.
	AssetTypeRule AssetType = "rule"

	// AssetTypeInstruction is always-on guidance concatenated into a managed
	// block in the project's committed memory file.
	AssetTypeInstruction AssetType = "instruction"

	// AssetTypeCommand is an asset the user invokes deliberately.
	AssetTypeCommand AssetType = "command"

	// AssetTypePersona is a delegated worker with its own model and tool budget.
	AssetTypePersona AssetType = "persona"
)

// assetTypeDirectories maps the directory that contains an asset to the type it
// names.
//
// The convention is not invented here: `skills/`, `commands/` and `agents/` are
// already how asset repositories are laid out, because that is how the
// harnesses themselves read them. `agents/` naming a persona is the one place
// harnaas reads a word it does not write — the directory name is the
// ecosystem's, and renaming it in the manifest would mean no existing
// repository could be referenced without an object per asset.
var assetTypeDirectories = map[string]AssetType{
	"skills":       AssetTypeSkill,
	"rules":        AssetTypeRule,
	"instructions": AssetTypeInstruction,
	"commands":     AssetTypeCommand,
	"agents":       AssetTypePersona,
}

// AssetTypes returns every type harnaas recognizes, in the order a diagnostic
// lists them.
//
// The order is the one the manifest's own vocabulary is written in rather than
// alphabetical, and it is fixed so two runs produce the same sentence.
func AssetTypes() []AssetType {
	return []AssetType{
		AssetTypeSkill,
		AssetTypeRule,
		AssetTypeInstruction,
		AssetTypeCommand,
		AssetTypePersona,
	}
}

// AssetRef is an asset entry's source string, parsed into where its content
// comes from and the path to it.
//
// Parsing settles the grammar and containment, and nothing else. It does not
// look the source key up, read the path or infer anything from it, because a
// string that is not one of the two accepted forms has no meaningful key and no
// meaningful path to check further.
type AssetRef struct {
	// SourceKey is the `sources` key the path is relative to. It is empty for
	// the project-local form, which is unambiguous because `sources` rejects an
	// empty key.
	SourceKey string

	// Path is the path to the asset, cleaned and slash-separated: within the
	// source for the keyed form, and relative to the project root — still
	// beginning `.harnaas/` — for the local form.
	Path string
}

// Local reports whether the reference is the project-local form.
func (r AssetRef) Local() bool {
	return r.SourceKey == ""
}

// assetSourceForms states both accepted forms, which is most of the fix for
// every string that is neither.
var assetSourceForms = fmt.Sprintf(
	"An asset source is either %q, naming a key declared in %q, or a project-local path such as %q.",
	"acme:skills/review", "sources", LocalRoot+"/rules/house-style.md",
)

// ParseAssetRef parses one asset entry's source string.
//
// The two accepted forms are distinguished by their prefix rather than by
// trying one and falling back to the other, so a string in neither form is
// reported as what it is instead of as a failed parse of a form its author
// never used.
func ParseAssetRef(index int, source string) (AssetRef, *Violation) {
	switch {
	case source == "":
		return AssetRef{}, assetSourceViolation(index,
			assetSubject(index)+" declares no source",
			fmt.Sprintf("Give the entry a source in %s. %s", FileName, assetSourceForms),
		)

	case isAbsolutePath(source):
		// Named separately from the general "neither form" case because an
		// absolute path is a specific misunderstanding — that harnaas installs
		// from anywhere on the machine — and the fix is to move the content
		// into the repository, not to add a prefix to the same path.
		return AssetRef{}, assetSourceViolation(index,
			fmt.Sprintf("%s names the absolute path %q, and every asset source is relative", assetSubject(index), source),
			fmt.Sprintf(
				"Move the content under %s/ in this repository and reference it from there, or declare its repository in %q. %s",
				LocalRoot, "sources", assetSourceForms,
			),
		)

	case strings.ContainsRune(source, '\\'):
		// A backslash is an ordinary filename character on Linux and a
		// separator on Windows, so a manifest containing one would name two
		// different files depending on who ran install. Rejecting it here, in
		// the grammar, is what keeps the same committed file mean the same
		// thing on every machine that reads it.
		return AssetRef{}, assetSourceViolation(index,
			fmt.Sprintf("%s has the source %q, which separates its path with a backslash", assetSubject(index), source),
			fmt.Sprintf("Write the path in %s with %q separators, as in %q.", FileName, "/", "acme:skills/review"),
		)

	case strings.HasPrefix(source, LocalRoot+"/"):
		return parseLocalRef(index, source)
	}

	key, rest, keyed := strings.Cut(source, ":")
	if !keyed || !validSourceKey(key) || rest == "" || strings.HasPrefix(rest, "/") {
		return AssetRef{}, notAnAssetForm(index, source)
	}

	cleaned := path.Clean(rest)
	if cleaned == "." || cleaned == ".." || strings.HasPrefix(cleaned, "../") {
		return AssetRef{}, assetSourceViolation(index,
			fmt.Sprintf("%s has the path %q, which leaves the root of the source %q", assetSubject(index), rest, key),
			fmt.Sprintf("Write the path in %s as one relative to the root of %q, without leading %q segments.", FileName, key, ".."),
		)
	}

	return AssetRef{SourceKey: key, Path: cleaned}, nil
}

// parseLocalRef checks that a project-local path stays under `.harnaas`.
//
// The check is textual and happens before anything is opened, because the
// content of a path that escapes must never be read — not even to report that
// it exists.
func parseLocalRef(index int, source string) (AssetRef, *Violation) {
	cleaned, contained := containedUnderLocalRoot(source)
	if !contained || cleaned == LocalRoot {
		return AssetRef{}, assetSourceViolation(index,
			fmt.Sprintf("%s has the local path %q, which does not stay inside %s", assetSubject(index), source, LocalRoot),
			fmt.Sprintf(
				"Move the content under %s/ and write the path without %q segments, as in %q.",
				LocalRoot, "..", LocalRoot+"/rules/house-style.md",
			),
		)
	}

	return AssetRef{Path: cleaned}, nil
}

// notAnAssetForm reports a source string in neither accepted form.
func notAnAssetForm(index int, source string) *Violation {
	return assetSourceViolation(index,
		fmt.Sprintf("%s has the source %q, which is neither of the two accepted forms", assetSubject(index), source),
		fmt.Sprintf("Rewrite the source in %s. %s", FileName, assetSourceForms),
	)
}

// isAbsolutePath reports whether a source string names a location on the
// machine rather than inside the project or a source.
//
// Both spellings are recognized on every platform: a manifest is committed and
// read on all of them, so a Windows path must be refused when the run happens
// to be on Linux and the other way round.
func isAbsolutePath(source string) bool {
	if strings.HasPrefix(source, "/") || strings.HasPrefix(source, `\\`) {
		return true
	}

	if len(source) < 3 || source[1] != ':' {
		return false
	}
	letter := source[0] | 0x20
	return letter >= 'a' && letter <= 'z' && (source[2] == '/' || source[2] == '\\')
}

// CheckSourceKey reports an asset referencing a key the `sources` block does
// not declare.
//
// It is separate from [ParseAssetRef] because the grammar is a property of the
// string and this is a property of the document: the same string is correct in
// one manifest and wrong in another, and only the second failure can name the
// keys that would have worked.
func CheckSourceKey(index int, ref AssetRef, sources map[string]Source) *Violation {
	if ref.Local() {
		return nil
	}
	if _, found := sources[ref.SourceKey]; found {
		return nil
	}

	known := make([]string, 0, len(sources))
	for key := range sources {
		known = append(known, quoted(key))
	}
	slices.Sort(known)

	fix := fmt.Sprintf("Declare %q in the %q block of %s, or correct the key on this entry.", ref.SourceKey, "sources", FileName)
	if len(known) > 0 {
		fix = fmt.Sprintf(
			"Use a key the %q block of %s declares (%s), or declare %q there.",
			"sources", FileName, strings.Join(known, ", "), ref.SourceKey,
		)
	}

	return assetSourceViolation(index,
		fmt.Sprintf("%s references the source key %q, which %q does not declare", assetSubject(index), ref.SourceKey, "sources"),
		fix,
	)
}

// InferType infers an asset's type from the directory containing it.
//
// It is separate from [InferID] because the object form suppresses inference
// one field at a time: an entry declaring `type` for a source laid out
// unconventionally still wants its id inferred from the leaf, and would
// otherwise be refused for a directory name nobody is relying on.
func InferType(index int, ref AssetRef) (AssetType, *Violation) {
	directory := path.Base(path.Dir(ref.Path))

	assetType, named := assetTypeDirectories[directory]
	if !named {
		return "", assetSourceViolation(index,
			fmt.Sprintf(
				"%s has the path %q, whose containing directory names none of the asset types",
				assetSubject(index), ref.Path,
			),
			fmt.Sprintf(
				"Either reference a path under one of %s, or write the entry in %s as an object declaring %q.",
				directoryList(), FileName, "type",
			),
		)
	}

	return assetType, nil
}

// InferID infers an asset's id from its path's leaf, with any file extension
// removed so `tone.md` and `tone` name the same asset.
func InferID(index int, ref AssetRef) (string, *Violation) {
	leaf := path.Base(ref.Path)

	// A leading dot is the extension by path.Ext's reckoning, so stripping
	// unconditionally would turn `.gitignore` into an empty id. Only a
	// non-empty remainder is an id.
	if stripped := strings.TrimSuffix(leaf, path.Ext(leaf)); stripped != "" {
		leaf = stripped
	}

	if leaf == "" || leaf == "." || leaf == ".." {
		return "", assetSourceViolation(index,
			fmt.Sprintf("%s has the path %q, whose last segment is not a name an asset can be identified by", assetSubject(index), ref.Path),
			fmt.Sprintf("Reference the asset's own file or directory, or write the entry in %s as an object declaring %q.", FileName, "id"),
		)
	}

	return leaf, nil
}

// directoryList renders the type-naming directories for a diagnostic, in the
// same fixed order [AssetTypes] uses.
func directoryList() string {
	byType := make(map[AssetType]string, len(assetTypeDirectories))
	for directory, assetType := range assetTypeDirectories {
		byType[assetType] = directory
	}

	names := make([]string, 0, len(byType))
	for _, assetType := range AssetTypes() {
		names = append(names, quoted(byType[assetType]+"/"))
	}
	return strings.Join(names, ", ")
}

// Package manifest decodes `harnaas.json`, the committed, hand-edited file in
// which a project declares which harness assets it wants and where they come
// from.
//
// The package covers the manifest end to end in two layers that meet at
// [Document]. Decoding turns bytes into that document and interprets none of
// it: a field it accepts is one it could read, not one harnaas has agreed to.
// Interpretation then reads the document — parsing a source value, parsing an
// asset's source string, inferring a type and an id from a path, defaulting
// targets and scope, and checking the result against the harness roster.
//
// The two share one package because harnaas extracts a package only to break an
// import cycle, and there is none to break here: both layers are imported by
// the same callers, and splitting them would put the roster on one side of a
// boundary that exists for no other reason. What separates them instead is when
// they stop. Decoding stops at the first failure, because a document that will
// not parse has no second problem to find. Interpretation reports every
// violation at once as a [Violation] list, because every asset entry is
// independent and fixing three mistakes should not take three runs.
//
// # Strict decoding
//
// The manifest is written by a person and reviewed by a team, so an unknown
// field is nearly always a typo and surfacing it immediately is worth the cost
// of refusing to run. That is the whole test: strictness follows who writes the
// file, not what the file is called. `harnaas.lock.json` is machine-written and
// therefore decodes leniently, because a newer binary introduces fields an
// older binary would otherwise reject, bricking the file for everyone still on
// the older version.
//
// The version field is what bounds that trade. It is read on its own, ahead of
// the strict pass, so a manifest written by a newer harnaas is refused with an
// explicit "upgrade harnaas" message rather than a confusing complaint about
// the first field this binary happens not to know.
//
// A decode failure returns no document at all. Half a manifest is not a smaller
// manifest — it is a different one, and installing from it would place a subset
// of what the project declared while reporting success.
//
// # Read-only
//
// Nothing here writes. Apart from `harnaas init` creating the file once, harnaas
// never writes, reformats or normalizes `harnaas.json`: it is the artifact a
// team reviews, and a tool that rewrites it makes its diffs untrustworthy. Every
// remedy this package reports is therefore phrased as the exact edit for a
// person to make, never as a command that would make it for them. A test over
// this package's own sources asserts no write call has crept in.
package manifest

// FileName is the manifest's only accepted name, at the repository root.
//
// It is a constant rather than a flag because the file is a project-level
// declaration: a `--manifest` pointing somewhere else would mean two developers
// in the same repository could install different asset sets and both be right.
const FileName = "harnaas.json"

// SupportedVersion is the manifest schema version this binary understands.
//
// A manifest declaring a greater version is refused with an upgrade message
// rather than read partially, because the fields this binary would silently
// ignore are exactly the ones the newer harnaas added to change what the
// document means.
const SupportedVersion = 1

// Document is a decoded manifest, field for field as written.
//
// Nothing in it has been interpreted: `Harnesses` and each entry's `Targets`
// are the strings the author typed rather than roster ids, and an asset's
// `Type`, `ID` and `Scope` are populated only where the object form declared
// them. An empty field here means "not declared", never "declared as the
// default" — the interpretation layer is what turns the first into the second,
// and it can only do that if decoding kept them distinguishable.
type Document struct {
	// Path is the file the document was decoded from, so a later diagnostic can
	// name it. It is empty for a document decoded from bytes.
	Path string

	// Version is the declared schema version, always a version this binary
	// understands — a greater one fails decoding rather than reaching a caller.
	Version int

	// Harnesses names the harnesses assets target by default. The list states a
	// guarantee ("we guarantee the declared assets work for these"), not
	// exclusivity: assets installed for one harness are routinely visible to
	// another.
	Harnesses []string

	// Sources maps a short key to a source string such as
	// `github:acme/assets@v1.2.0`. The key is what asset entries reference, so a
	// repository and a ref appear exactly once each.
	Sources map[string]string

	// Assets is the declared asset list in document order. Order is preserved
	// because it is the order the author reads in review, and every diagnostic
	// naming an entry names its index in this slice.
	Assets []AssetEntry
}

// AssetEntry is one entry of the `assets` array, in whichever form it was
// written.
//
// The string form carries only a source; the object form may additionally
// declare a type, an id, a target list or a scope, each suppressing what would
// otherwise be inferred or defaulted for that one field.
type AssetEntry struct {
	// Index is the entry's position in the `assets` array. It is not decoded
	// from the document — it is where the entry was found, and it is how every
	// diagnostic points the author at the line to edit, since an entry has no
	// other stable name until its id is known.
	Index int

	// ObjectForm records whether the entry was written as an object rather than
	// a bare source string. Some remedies are only available in the object form,
	// so a message can direct an author there only if it knows they are not
	// already using it.
	ObjectForm bool

	// Source is the entry's source string: the `<sourceKey>:<path>` or
	// `.harnaas/…` form, exactly as written and not yet parsed.
	Source string

	// Type overrides the type the path would imply. Empty means undeclared.
	Type string

	// ID overrides the id the path's leaf would imply. Empty means undeclared.
	ID string

	// Targets overrides the manifest's `harnesses` list for this asset. A nil
	// slice means undeclared; an empty non-nil slice means the author declared
	// an empty list, which is a validation error rather than a default, because
	// the asset could never be installed anywhere.
	Targets []string

	// Scope overrides the default `project` scope. Empty means undeclared.
	Scope string
}

package manifest

import (
	"fmt"
	"path"
	"strconv"
	"strings"
)

// LocalRoot is the directory a project's own asset content lives under,
// relative to the project root.
//
// One directory rather than any path the author likes is what makes a local
// asset auditable: everything harnaas may read out of the repository is in one
// place, and a path that leaves it is a mistake harnaas can name without
// knowing anything about the project's layout.
const LocalRoot = ".harnaas"

// SourceKind names how harnaas obtains a source's content.
//
// The kind travels inside the source string rather than in a field of its own
// so a future kind slots into the one grammar instead of growing a second one.
// Parsing recognizes the kind and stops there — nothing here fetches, resolves
// or stats anything — so a manifest can be validated with no network and no
// filesystem, which is what lets `lint` report a bad source offline.
type SourceKind string

const (
	// SourceKindGitHub is a path within a GitHub repository at a ref.
	SourceKindGitHub SourceKind = "github"

	// SourceKindLocal is a path under the project's own `.harnaas` directory.
	SourceKindLocal SourceKind = "local"
)

// sourceKinds is every registered kind, in the order every message lists them.
//
// A slice rather than a map keeps that order identical on every run, which is
// what makes two people's terminals show the same diagnostic for the same file.
var sourceKinds = []SourceKind{SourceKindGitHub, SourceKindLocal}

// Source is one parsed `sources` entry: where a group of assets comes from,
// declared once and referenced by key.
//
// Nothing in it has been resolved. `Repository` is the text between the kind
// and the ref, checked for shape and not for existence, and `Ref` is the text
// after `@`, not a commit. Turning either into content is `install`'s job, and
// keeping it out of here is what makes validation a pure function of the file.
type Source struct {
	// Key is the short name asset entries reference. It is carried on the
	// parsed source so a diagnostic raised downstream can still name the
	// declaration that caused it.
	Key string

	// Kind is the registered kind, already checked against [sourceKinds].
	Kind SourceKind

	// Repository is what the kind names: an `owner/repository` pair for GitHub,
	// a project-relative directory under `.harnaas` for a local source.
	Repository string

	// Ref is the ref a GitHub source is pinned to, exactly as written. It is
	// empty for a local source, which has nothing to pin.
	Ref string
}

// String renders the source back in the form it was written, so a message can
// quote a parsed source without the caller reassembling it.
func (s Source) String() string {
	value := string(s.Kind) + ":" + s.Repository
	if s.Ref == "" {
		return value
	}
	return value + "@" + s.Ref
}

// ParseSource parses one `sources` value into its kind, repository and ref, and
// resolves nothing.
//
// The key is a parameter rather than something recovered from the value because
// every diagnostic here names it: an author reading "the source is malformed"
// has to find which one, and the map key is the only name the declaration has.
func ParseSource(key, value string) (Source, *Violation) {
	if violation := validateSourceKey(key); violation != nil {
		return Source{}, violation
	}

	kindText, remainder, hasKind := strings.Cut(value, ":")
	if !hasKind || kindText == "" || remainder == "" {
		return Source{}, sourceViolation(key,
			fmt.Sprintf("the source %q is %q, which does not name a source kind", key, value),
			fmt.Sprintf(
				"Write the value of %q in %s as a kind, a repository and a ref, as in %q.",
				key, FileName, "github:acme/assets@v1.2.0",
			),
		)
	}

	repository, ref := splitRef(remainder)

	// Every registered kind is listed, so a kind added to [sourceKinds] without
	// a case here reports itself as unrecognized rather than being parsed by
	// whichever branch happened to be last.
	switch SourceKind(kindText) {
	case SourceKindGitHub:
		return parseGitHubSource(key, repository, ref)
	case SourceKindLocal:
		return parseLocalSource(key, repository, ref)
	default:
		return Source{}, sourceViolation(key,
			fmt.Sprintf("the source %q names the kind %q, which harnaas does not recognize", key, kindText),
			fmt.Sprintf("Change %q in %s to use a kind harnaas knows: %s.", key, FileName, kindList()),
		)
	}
}

// parseGitHubSource checks the two things a GitHub source must state: which
// repository, and which ref.
func parseGitHubSource(key, repository, ref string) (Source, *Violation) {
	owner, name, hasOwner := strings.Cut(repository, "/")
	if !hasOwner || owner == "" || name == "" || strings.Contains(name, "/") {
		return Source{}, sourceViolation(key,
			fmt.Sprintf("the source %q names the repository %q, which is not an owner and a repository", key, repository),
			fmt.Sprintf(
				"Write the repository of %q in %s as owner/repository, as in %q.",
				key, FileName, "github:acme/assets@v1.2.0",
			),
		)
	}

	// A GitHub source with no ref is an unpinned dependency, and a manifest
	// whose whole purpose is declaring which version of somebody else's content
	// this repository trusts cannot have one. Defaulting to a branch would make
	// two installs of the same manifest produce different files.
	if ref == "" {
		return Source{}, sourceViolation(key,
			fmt.Sprintf("the source %q declares no ref, so it names no particular version of %q", key, repository),
			fmt.Sprintf(
				"Pin %q in %s to a tag or commit with an @ suffix, as in %q.",
				key, FileName, "github:acme/assets@v1.2.0",
			),
		)
	}

	return Source{Key: key, Kind: SourceKindGitHub, Repository: repository, Ref: ref}, nil
}

// parseLocalSource checks that a local source names a directory inside the
// project's `.harnaas`, and that it pins nothing.
func parseLocalSource(key, repository, ref string) (Source, *Violation) {
	if ref != "" {
		return Source{}, sourceViolation(key,
			fmt.Sprintf("the source %q is local and declares the ref %q, and content in this repository has no ref to be at", key, ref),
			fmt.Sprintf("Remove the %q suffix from %q in %s.", "@"+ref, key, FileName),
		)
	}

	cleaned, contained := containedUnderLocalRoot(repository)
	if !contained {
		return Source{}, sourceViolation(key,
			fmt.Sprintf("the source %q names the local path %q, which is not inside %s", key, repository, LocalRoot),
			fmt.Sprintf(
				"Point %q in %s at a directory under %s/, relative to the repository root.",
				key, FileName, LocalRoot,
			),
		)
	}

	return Source{Key: key, Kind: SourceKindLocal, Repository: cleaned}, nil
}

// validateSourceKey rejects a key an asset entry could not reference.
//
// The asset string grammar splits on the first colon, so a key containing one
// could never be written on an asset; a key containing a slash would be
// indistinguishable from a path. An empty key is rejected because the parsed
// asset reference uses an empty source key to mean the project-local form.
func validateSourceKey(key string) *Violation {
	switch {
	case key == "":
		return sourceViolation(key,
			"the "+quoted("sources")+" block declares an entry with an empty key",
			fmt.Sprintf("Give every entry in %s a short name, such as %q.", quoted("sources"), "acme"),
		)
	case !validSourceKey(key):
		return sourceViolation(key,
			fmt.Sprintf("the source key %q contains a character an asset entry could not reference it by", key),
			fmt.Sprintf(
				"Rename the key in %s to letters, digits, %q, %q or %q, such as %q.",
				FileName, "-", "_", ".", "acme",
			),
		)
	}
	return nil
}

// validSourceKey reports whether a key is one an asset entry could reference,
// which is the same question [validateSourceKey] answers with a diagnostic. The
// asset grammar asks it about text that may not be a key at all, where building
// a violation to discard would be the wrong shape.
func validSourceKey(key string) bool {
	return key != "" && !strings.ContainsAny(key, ":/\\ ")
}

// splitRef separates a ref from what precedes it, taking the last `@` so a
// repository containing one keeps it.
func splitRef(remainder string) (repository, ref string) {
	at := strings.LastIndex(remainder, "@")
	if at < 0 {
		return remainder, ""
	}
	return remainder[:at], remainder[at+1:]
}

// containedUnderLocalRoot reports whether a project-relative path stays inside
// `.harnaas`, returning it in cleaned form.
//
// The check runs on the text, before anything is opened, because a path that
// escapes must never be read — not even to discover that it exists. Cleaning
// first is what makes `.harnaas/../../etc` fail here rather than resolve
// somewhere it should not.
//
// A backslash is rejected outright rather than treated as a separator: it is an
// ordinary filename character on Linux and a separator on Windows, so a path
// containing one would mean two different things depending on who ran install.
func containedUnderLocalRoot(candidate string) (string, bool) {
	if candidate == "" || strings.ContainsRune(candidate, '\\') || strings.HasPrefix(candidate, "/") {
		return "", false
	}

	cleaned := path.Clean(candidate)
	if cleaned == LocalRoot || strings.HasPrefix(cleaned, LocalRoot+"/") {
		return cleaned, true
	}
	return "", false
}

// kindList renders the registered kinds for a diagnostic.
func kindList() string {
	names := make([]string, 0, len(sourceKinds))
	for _, kind := range sourceKinds {
		names = append(names, strconv.Quote(string(kind)))
	}
	return strings.Join(names, ", ")
}

// quoted renders a field or block name the way every diagnostic quotes one.
func quoted(name string) string {
	return strconv.Quote(name)
}

package manifest

import (
	"fmt"
	"path/filepath"
)

// DecodeError reports a manifest harnaas could not decode.
//
// One type covers every decoding failure — malformed JSON, an unknown field, a
// wrongly shaped field, a version this binary cannot read — because they all
// end in the same place: a person opening `harnaas.json` and editing one line.
// What differs between them is the sentence, not the shape, and the shape is
// what a caller would branch on.
type DecodeError struct {
	// Path is the manifest the failure came from. It is empty for a document
	// decoded from bytes, where the message falls back to naming the file.
	Path string

	// Problem states what is wrong, in one line.
	Problem string

	// Fix states the edit that resolves it. It is always an edit for a person to
	// make: harnaas does not write this file.
	Fix string

	// Line and Column locate the problem in the file, both 1-based, and are zero
	// where the failure has no single location — an entry named by its index, or
	// a version that is wrong wherever it was written.
	Line, Column int
}

// Error renders the location, the problem, a blank line, and the fix.
func (e *DecodeError) Error() string {
	return fmt.Sprintf("%s: %s\n\n%s", e.where(), e.Problem, e.Fix)
}

// where names the file and, where one is known, the line and column inside it,
// in the `file:line:column` form an editor and a terminal both make clickable.
func (e *DecodeError) where() string {
	name := e.Path
	if name == "" {
		name = FileName
	}
	if e.Line <= 0 {
		return name
	}
	return fmt.Sprintf("%s:%d:%d", name, e.Line, e.Column)
}

// NotFoundError reports a project with no manifest at its root.
//
// It is a distinct type because "there is no manifest yet" is not a broken
// manifest: it is the ordinary state of a project before `harnaas init`, and a
// caller may want to say something different about it.
type NotFoundError struct {
	// Root is the project root that was searched, so the message can show which
	// project harnaas resolved — the usual cause of surprise here is being in a
	// different repository than expected.
	Root string
}

// Error names the project searched and the command that creates the file.
func (e *NotFoundError) Error() string {
	return fmt.Sprintf(
		"no %s found in %s\n\n"+
			"Run `harnaas init` in that project to create one.",
		FileName, e.Root,
	)
}

// SubdirectoryError reports a `harnaas.json` below the project root.
//
// Such a file is an error rather than something harnaas quietly skips. A file
// with this name that harnaas ignores is worse than one it rejects: its author
// believes it is declaring assets, and every command silently disagrees.
// Merging it is not on the table either, since the effective asset set would
// then depend on which directory a command ran from, which is exactly the
// variation harnaas exists to remove.
type SubdirectoryError struct {
	// Path is the offending manifest's absolute path.
	Path string

	// Root is the project root, whose manifest is the only one harnaas reads.
	Root string
}

// Error names the file that will never be read and states the only manifest
// harnaas does read.
func (e *SubdirectoryError) Error() string {
	shown := e.Path
	if relative, err := filepath.Rel(e.Root, e.Path); err == nil {
		shown = filepath.ToSlash(relative)
	}

	return fmt.Sprintf(
		"found a second manifest at %s, which harnaas never reads\n\n"+
			"harnaas reads only the %s at the repository root (%s). "+
			"Move any entries you need into that file and delete %s.",
		shown, FileName, e.Root, shown,
	)
}

package manifest

import (
	"context"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"strings"

	"github.com/harnaas/harnaas/cmd/harnaas/cli/paths"
)

// skippedDirs are directory names the search for a stray manifest does not
// descend into.
//
// A `harnaas.json` inside a dependency tree belongs to that dependency, not to
// this project: a vendored library that manages its own harness assets would
// otherwise make every harnaas command in the parent repository fail with a
// diagnostic about a file the author cannot edit. Dot-directories are skipped
// for the same reason plus a plainer one — `.git` is large and holds nothing a
// person declared.
var skippedDirs = map[string]bool{
	"node_modules": true,
	"vendor":       true,
}

// Path returns where the manifest lives for the project carried in ctx.
//
// It is the one place the file's location is assembled, so `init` writing the
// manifest and `install` reading it can never disagree about where it is.
func Path(ctx context.Context) (string, error) {
	root, err := paths.ProjectRoot(ctx)
	if err != nil {
		return "", err
	}
	return filepath.Join(root, FileName), nil
}

// Load finds the project's manifest and decodes it.
//
// The manifest is resolved from the project root carried in ctx rather than
// from where the command was run, so every command reads the same declarations
// from every directory in the repository.
func Load(ctx context.Context) (*Document, error) {
	root, err := paths.ProjectRoot(ctx)
	if err != nil {
		return nil, err
	}
	return loadFrom(root)
}

// loadFrom is Load once the project root is known.
//
// The search for a stray manifest runs before the root manifest is read, and
// therefore before the "no manifest here" message too: a project whose only
// `harnaas.json` sits in a subdirectory is not a project without a manifest,
// and telling its author to run `harnaas init` would answer a question they did
// not ask.
func loadFrom(root string) (*Document, error) {
	stray, err := findSubdirectoryManifest(root)
	if err != nil {
		return nil, err
	}
	if stray != "" {
		return nil, &SubdirectoryError{Path: stray, Root: root}
	}

	path := filepath.Join(root, FileName)

	//nolint:gosec // G304: the path is the project root harnaas resolved plus a constant file name, and it is opened for reading only.
	data, err := os.ReadFile(path)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, &NotFoundError{Root: root}
		}
		return nil, fmt.Errorf("read %s: %w", path, err)
	}

	return decode(data, path)
}

// findSubdirectoryManifest returns the path of the first `harnaas.json` below
// root, or an empty string if there is none.
//
// The walk stops at the first match because one is enough to fail the run, and
// it skips the directories a project's own declarations never live in. A
// deliberate consequence is that harnaas refuses to run rather than quietly
// reading the root manifest: a file with this name that harnaas ignores is
// worse than one it rejects, because its author believes it is declaring
// assets.
func findSubdirectoryManifest(root string) (string, error) {
	found := ""

	err := filepath.WalkDir(root, func(path string, entry fs.DirEntry, walkErr error) error {
		if walkErr != nil {
			// An unreadable directory is not evidence of a stray manifest, and
			// it is not this function's failure to report: whatever the command
			// actually needs from that directory will fail with a message about
			// the thing it needed.
			return nil //nolint:nilerr // Deliberate: an unreadable subtree cannot answer the question, so the search moves on.
		}

		if entry.IsDir() {
			if path == root {
				return nil
			}
			if skippedDirs[entry.Name()] || strings.HasPrefix(entry.Name(), ".") {
				return fs.SkipDir
			}
			return nil
		}

		if entry.Name() == FileName && filepath.Dir(path) != root {
			found = path
			return fs.SkipAll
		}
		return nil
	})
	if err != nil {
		return "", fmt.Errorf("search %s for a second %s: %w", root, FileName, err)
	}

	return found, nil
}

